package org.transittr.tests;
import android.app.*;import android.os.*;import android.content.*;import android.widget.*;import android.view.*;import java.lang.reflect.*;import java.util.*;
/** Real stop resolution, all-city route data and the actual blue-code click handler. */
public final class RoutePinCheck extends Instrumentation {
 private Activity activity;private volatile boolean sample;private int peak,count;private ClassLoader loader;
 private void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 private Object field(Object object,String name)throws Exception{Field f=object.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(object);}
 private void set(String name,Object value)throws Exception{Field f=activity.getClass().getDeclaredField(name);f.setAccessible(true);f.set(activity,value);}
 private void call(String name)throws Exception{Method m=activity.getClass().getDeclaredMethod(name);m.setAccessible(true);m.invoke(activity);}
 private void status(String value){Bundle b=new Bundle();b.putString("stream",value+"\n");sendStatus(1,b);}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();boolean passed=false;try{
  sample=true;new Thread(new Runnable(){public void run(){while(sample){Debug.MemoryInfo info=new Debug.MemoryInfo();Debug.getMemoryInfo(info);peak=Math.max(peak,info.getTotalPss());count++;try{Thread.sleep(100);}catch(InterruptedException e){return;}}}}).start();
  getTargetContext().deleteDatabase("transit-v110.sqlite");
  activity=startActivitySync(new Intent().setClassName("org.transittr","org.transittr.TransitActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));loader=activity.getClassLoader();waitForIdleSync();
  Class<?> resolver=loader.loadClass("org.transittr.StopResolver"),storeClass=loader.loadClass("org.transittr.CatalogStore"),itemClass=loader.loadClass("org.transittr.CatalogStore$Item"),repo=loader.loadClass("org.transittr.RouteRepository");
  int[] cities={0,1,2,6};String[] codes={"10940","224672","21050","27"},lines={"263-7","500T","446","6-A"};
  for(int i=0;i<cities.length;i++){
   Object stop=resolver.getMethod("resolve",Context.class,Integer.TYPE,String.class).invoke(null,activity,cities[i],codes[i]);check(stop!=null,"stop coordinates city="+cities[i]);check(codes[i].equals(field(stop,"code")),"exact requested stop number");status("STOP_PIN="+cities[i]+";"+codes[i]+";"+field(stop,"name")+";"+field(stop,"lat")+";"+field(stop,"lon"));
   Object store=storeClass.getConstructor(Context.class).newInstance(activity);Object item=null;
   try{Object page=storeClass.getMethod("page",Integer.TYPE,Integer.TYPE,String.class,Integer.TYPE).invoke(store,cities[i],0,lines[i],0);for(Object candidate:(ArrayList)field(page,"items"))if(lines[i].equals(field(candidate,"code"))){item=candidate;break;}check(item!=null,"catalogue route "+lines[i]);}finally{storeClass.getMethod("close").invoke(store);}
   Object route=repo.getMethod("load",Context.class,Integer.TYPE,itemClass,Boolean.TYPE).invoke(null,activity,cities[i],item,false);ArrayList parts=(ArrayList)field(route,"parts");check(!parts.isEmpty(),"route has drawable points "+lines[i]);status("ROUTE="+cities[i]+";"+lines[i]+";PARTS="+parts.size()+";STOPS="+((ArrayList)field(route,"stops")).size()+";SCHEMATIC="+field(route,"schematic"));
  }
  Object schedule=loader.loadClass("org.transittr.EgoSchedule").getMethod("get",Context.class,String.class,Boolean.TYPE).invoke(null,activity,"481",true);check(schedule.toString().contains("stops"),"official timetable response");check(!((Boolean)schedule.getClass().getMethod("optBoolean",String.class,Boolean.TYPE).invoke(schedule,"stale",false)).booleanValue(),"official timetable synchronized without cache fallback");status("EGO_SCHEDULE_SYNC=481_PASS");
  runOnMainSync(new Runnable(){public void run(){try{call("stopTracking");set("city",Integer.valueOf(0));set("screen",Integer.valueOf(0));set("snapshot",null);call("build");((EditText)field(activity,"stopInput")).setText("10940");((EditText)field(activity,"lineInput")).setText("");((Button)field(activity,"start")).performClick();}catch(Exception e){throw new RuntimeException(e);}}});
  for(int i=0;i<250&&(field(activity,"snapshot")==null||field(activity,"selectedStop")==null);i++){Thread.sleep(200);waitForIdleSync();}
  check(field(activity,"snapshot")!=null,"real live stop query completed");check(field(activity,"selectedStop")!=null,"selected pin attached to live map");
  final ArrayList rows=(ArrayList)field(field(activity,"snapshot"),"rows");check(!rows.isEmpty(),"live departure rows available");
  runOnMainSync(new Runnable(){public void run(){try{LinearLayout list=(LinearLayout)field(activity,"bottomRows");((LinearLayout)list.getChildAt(0)).getChildAt(0).performClick();}catch(Exception e){throw new RuntimeException(e);}}});
  for(int i=0;i<250&&field(activity,"liveRoute")==null;i++){Thread.sleep(200);waitForIdleSync();}
  check(field(activity,"liveRoute")!=null,"blue line number click loads route");check(((Integer)field(activity,"screen")).intValue()==0,"route stays on same live map");check("10940".equals(field(field(activity,"selectedStop"),"code")),"route retains queried stop pin");status("LIVE_ROUTE_CLICK_PASS;ROWS="+rows.size()+";CENTER="+field(field(activity,"map"),"lat")+","+field(field(activity,"map"),"lon")+";ZOOM="+field(field(activity,"map"),"zoom"));Thread.sleep(5000);status("CAPTURE=LIVE_ROUTE_STOP_PIN");Thread.sleep(6000);
  runOnMainSync(new Runnable(){public void run(){try{((TextView)field(activity,"mapBadge")).performClick();}catch(Exception e){throw new RuntimeException(e);}}});check(field(activity,"liveRoute")==null,"clear overlay action");check(field(activity,"selectedStop")!=null,"clear route keeps stop pin");status("CAPTURE=LIVE_STOP_PIN");Thread.sleep(6000);
  runOnMainSync(new Runnable(){public void run(){try{call("stopTracking");set("screen",Integer.valueOf(3));call("build");}catch(Exception e){throw new RuntimeException(e);}}});
  Object catalog=field(activity,"catalog");for(int i=0;i<100&&((ArrayList)field(catalog,"items")).isEmpty();i++){Thread.sleep(100);waitForIdleSync();}check(((ArrayList)field(catalog,"items")).size()==50,"catalogue first page");status("CAPTURE=CATALOG");Thread.sleep(6000);
  final Object activeCatalog=catalog;runOnMainSync(new Runnable(){public void run(){try{((ListView)field(activeCatalog,"list")).setSelection(49);}catch(Exception e){throw new RuntimeException(e);}}});for(int i=0;i<100&&((ArrayList)field(catalog,"items")).size()<100;i++){Thread.sleep(100);waitForIdleSync();}check(((ArrayList)field(catalog,"items")).size()>=100,"catalogue scroll pagination");
  runOnMainSync(new Runnable(){public void run(){try{((EditText)field(activeCatalog,"search")).setText("263-7");}catch(Exception e){throw new RuntimeException(e);}}});Thread.sleep(1000);waitForIdleSync();check(((ArrayList)field(catalog,"items")).size()==1,"exact line search");
  runOnMainSync(new Runnable(){public void run(){try{ListView list=(ListView)field(activeCatalog,"list");list.performItemClick(list.getChildAt(0),0,list.getAdapter().getItemId(0));}catch(Exception e){throw new RuntimeException(e);}}});check(((Integer)field(activity,"screen")).intValue()==4,"catalogue native route screen");Object routeScreen=field(activity,"routeScreen");for(int i=0;i<150&&field(routeScreen,"route")==null;i++){Thread.sleep(100);waitForIdleSync();}check(field(routeScreen,"route")!=null,"native route loaded");status("CAPTURE=CATALOG_ROUTE");Thread.sleep(6000);
  final Object activeRoute=routeScreen;runOnMainSync(new Runnable(){public void run(){try{Method times=activeRoute.getClass().getDeclaredMethod("times",Boolean.TYPE);times.setAccessible(true);times.invoke(activeRoute,false);}catch(Exception e){throw new RuntimeException(e);}}});Thread.sleep(1000);status("CAPTURE=EGO_TIMETABLE");Thread.sleep(6000);status("CATALOG_PAGING_SEARCH_ROUTE_PASS");
  passed=true;result.putString("stream","PASS Android "+Build.VERSION.RELEASE+" API "+Build.VERSION.SDK_INT+"; ALL_CITY_ROUTES=4; STOP_PINS=4; PEAK_PSS_KIB="+peak+"; SAMPLES="+count+"\n");
 }catch(Throwable e){java.io.StringWriter out=new java.io.StringWriter();e.printStackTrace(new java.io.PrintWriter(out));result.putString("stream","FAIL Android "+Build.VERSION.RELEASE+"\n"+out);}finally{sample=false;}finish(passed?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}
}
